-- ExamGrind verified daily current-affairs desk: 2 November 2026.
-- Every item below is independently checked against the linked competent official release.

insert into public.current_affairs_briefs (
  slug, published_on, title, summary, why_it_matters, background,
  source_title, source_url, source_publisher, source_published_on,
  prelims_takeaways, quick_check, visual_data, status, reviewed_at
) values
(
$$2026-11-02-digi-yatra-international-trials$$, $$2026-11-02$$,
$$Digi Yatra begins international-passenger trials at seven airports$$,
$$The Ministry of Civil Aviation has begun Digi Yatra trials for eligible Indian nationals with e-passports on selected international Air India and IndiGo flights. The November-December trial covers seven airports and will inform a planned wider rollout in 2027.$$,
$$This is a useful digital-public-infrastructure and aviation-governance update. It links facial-recognition-based airport processing with e-passport credentials while making clear that a trial is not a replacement for immigration or travel-document checks.$$,
$$The trial airports are Delhi, Bengaluru, Hyderabad, Cochin, Mumbai, Chennai and Amritsar. A user creates an e-passport-based Verifiable Credential in the Digi Yatra app by reading the passport MRZ and chip through NFC, then uses it at enabled touchpoints. The official release says the platform already serves domestic journeys; international use remains a limited trial.$$,
$$Digi Yatra Begins International Passenger Trials at Seven Airports$$,
$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2331200$$,
$$Ministry of Civil Aviation / Press Information Bureau$$, $$2026-11-01$$,
$$["The trials run during November-December 2026 at seven named airports.","They are for eligible Indian nationals holding e-passports on selected flights.","The e-passport credential uses the MRZ and NFC chip read in the Digi Yatra app.","Digi Yatra complements rather than replaces airline checks, immigration and travel documents."]$$::jsonb,
$$[{"question":"Does an international Digi Yatra trial remove the need for immigration and travel documents?","answer":"No. The release explicitly says passengers must still complete the applicable airline, immigration and travel formalities."}]$$::jsonb,
$${"title":"International Digi Yatra trial","steps":["An eligible traveller creates an e-passport credential in the app.","Enabled airport touchpoints read the credential during the trial.","Airline and immigration processes continue separately.","Passenger feedback informs decisions on a wider rollout."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-02-coal-imports-august$$, $$2026-11-02$$,
$$August coal imports fall 5.83% year on year, Ministry of Coal reports$$,
$$India imported 104.57 million tonnes of coal in August 2026, 5.83% below the 111.05 million tonnes recorded a year earlier, according to the Ministry of Coal. Imports for blending at domestic coal-based power plants fell more sharply than the overall total.$$,
$$Energy-security questions often test the distinction between coal production, consumption and imports. This release provides a concrete example of how domestic availability and blending needs can affect import demand without proving that imports have ceased.$$,
$$Power-sector coal imports were 21.32 million tonnes, down 6.39% year on year. Imports for blending at domestic coal-based plants were 3.00 million tonnes, down 35.23%, while imports by plants designed to use imported coal were 18.31 million tonnes, a marginal increase. The figures concern August and should not be treated as a full-year energy balance.$$,
$$Coal Imports Decline by 5.83% in August 2026, Reflecting Reduced Import Dependence$$,
$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2331073$$,
$$Ministry of Coal / Press Information Bureau$$, $$2026-11-01$$,
$$["Total coal imports in August 2026 were 104.57 million tonnes.","The reported year-on-year decline was 5.83%.","Imports for blending at domestic coal-based plants were 3.00 million tonnes.","Imported-coal-based plants are designed to operate primarily on imported coal."]$$::jsonb,
$$[{"question":"Did the August data show that all coal imports had ended?","answer":"No. Imports declined, but India still imported 104.57 million tonnes during the month."}]$$::jsonb,
$${"title":"Reading coal-import data","steps":["Domestic supply and demand shape import needs.","Some power plants use imports for blending.","Imported-coal-based plants have a distinct fuel requirement.","Monthly import data measure a period, not a permanent policy outcome."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-02-air-chief-marshal-ashutosh-dixit-vayu$$, $$2026-11-02$$,
$$Air Chief Marshal Ashutosh Dixit assumes charge as the 29th Chief of Air Staff$$,
$$Air Chief Marshal Ashutosh Dixit assumed charge as the 29th Chief of the Air Staff on 1 November. In his opening address, he set out the IAF's guiding theme, VAYU, covering vigilance and readiness, Aatmanirbharta, innovation-oriented Yukti and unity of effort.$$,
$$The Chief of Air Staff is a high-value defence-institutions fact. The VAYU outline also offers a compact way to connect operational preparedness, indigenous capability, emerging technology and jointness in contemporary defence questions.$$,
$$The release identifies him as an Experimental Test Pilot and Qualified Flying Instructor with over 3,500 flying hours. Before taking charge, he held roles including Chief of Integrated Defence Staff to the Chairman, Chiefs of Staff Committee, Air Officer Commanding-in-Chief of Central Air Command and Vice Chief of the Air Staff. A service-chief vision statement is a strategic direction, not by itself a new defence procurement or statute.$$,
$$Air Chief Marshal Ashutosh Dixit assumes charge as the 29th Chief of the Air Staff; unveils 'VAYU' as guiding vision for the Indian Air Force$$,
$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2331212$$,
$$Ministry of Defence / Press Information Bureau$$, $$2026-11-01$$,
$$["Air Chief Marshal Ashutosh Dixit is the 29th Chief of the Air Staff.","He assumed charge on 1 November 2026.","VAYU includes Vigilance, Victory and Readiness; Aatmanirbharta; Yukti; and Unity of Effort.","The release links Unity of Effort with jointness among the services and national agencies."]$$::jsonb,
$$[{"question":"What does the 'U' in the IAF's VAYU theme stand for?","answer":"Unity of Effort, with emphasis on jointness with the Army, Navy and national agencies."}]$$::jsonb,
$${"title":"VAYU strategic frame","steps":["Readiness protects operational capability.","Aatmanirbharta seeks indigenous capability.","Yukti applies innovation to doctrine and technology.","Unity of Effort connects the services and national agencies."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-02-cisf-functional-sector-structure$$, $$2026-11-02$$,
$$CISF adopts functional sector-based structure for critical-infrastructure security$$,
$$The Central Industrial Security Force has replaced its territorial command arrangement with a functional sector-based structure from 1 November 2026. Units are now grouped by the type of installation they protect, rather than only by geography.$$,
$$This is a significant internal-security institutional change. It helps students connect CISF's mandate with the specialised risks of power plants, coal mines, steel facilities, airports, metro systems and other critical infrastructure.$$,
$$The restructuring was undertaken with Ministry of Home Affairs concurrence. The release says the earlier model could place more than 50 diverse units under one Sector Headquarters; the new arrangement creates installation-focused commands, including Power-I and Power-II, Coal and Steel sectors. It changes supervision and coordination, rather than creating a new central armed police force.$$,
$$CISF Adopts Functional Sector-Based Structure to Strengthen Critical Infrastructure Security and Operational Efficiency$$,
$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2331246$$,
$$Ministry of Home Affairs / Press Information Bureau$$, $$2026-11-01$$,
$$["The functional structure took effect on 1 November 2026.","CISF moved away from a territorial command system.","Units are grouped by installation type for specialised supervision.","The restructuring has Ministry of Home Affairs concurrence."]$$::jsonb,
$$[{"question":"Under the revised CISF arrangement, what is the basic organising principle: geography or type of installation?","answer":"Type of installation; the structure is functional and sector-based rather than territorial."}]$$::jsonb,
$${"title":"Functional CISF supervision","steps":["Critical infrastructure faces sector-specific security risks.","CISF groups comparable installations into a functional sector.","Sector leaders develop specialised oversight.","Coordination and decision-making are intended to become faster and more focused."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-02-bengaluru-mumbai-vande-bharat-sleeper$$, $$2026-11-02$$,
$$Bengaluru-Mumbai Vande Bharat Sleeper Express is flagged off$$,
$$Indian Railways flagged off the SMVT Bengaluru-Chhatrapati Shivaji Maharaj Terminus Mumbai Vande Bharat Sleeper Express, expanding overnight Vande Bharat Sleeper connectivity between two major metropolitan centres.$$,
$$The launch is relevant to transport infrastructure and rail-modernisation questions. It also helps distinguish a sleeper service designed for overnight travel from the broader Vande Bharat brand and from an approval or proposed route that has not yet begun operations.$$,
$$The official release says the train runs via Anantapur and Guntakal in Andhra Pradesh and Raichur, Yadgir and Kalaburagi in Karnataka. It follows the Howrah-Guwahati sleeper service introduced in January 2026 and the Varanasi-New Delhi sleeper train flagged off the previous day. The announcement concerns a passenger service, not a new rail-zone or a change in railway administration.$$,
$$Union Minister for Railways flags off Bengaluru-Mumbai Vande Bharat Sleeper Express Train$$,
$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2331297$$,
$$Ministry of Railways / Press Information Bureau$$, $$2026-11-01$$,
$$["The service links SMVT Bengaluru with CSMT Mumbai.","It is a Vande Bharat Sleeper Express for overnight travel.","The route includes locations in Andhra Pradesh and Karnataka before Mumbai.","The release places it after the Howrah-Guwahati and Varanasi-New Delhi sleeper services."]$$::jsonb,
$$[{"question":"Which Mumbai terminus is named in the Bengaluru-Mumbai Vande Bharat Sleeper service?","answer":"Chhatrapati Shivaji Maharaj Terminus (CSMT)."}]$$::jsonb,
$${"title":"Overnight rail-connectivity expansion","steps":["Railways introduce a sleeper service on an inter-city corridor.","The route links regional centres across states.","Passengers gain an overnight travel option.","The service adds to the Vande Bharat Sleeper network."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-02-coal-india-october-records$$, $$2026-11-02$$,
$$Coal India reports record monthly production and supply for October 2026$$,
$$Coal India Limited reported its highest monthly coal production and total supply in October 2026: 67.2 million tonnes produced and 70.3 million tonnes supplied. Supply to the power sector was 57.1 million tonnes.$$,
$$The update is relevant for energy-sector and public-enterprise questions because Coal India is the country's leading coal producer. It also reinforces that production, supply and railway evacuation are separate operating indicators.$$,
$$The company reported year-on-year growth of 19% for both total supply and production. Average daily railway rake loading for the power sector reached 310 rakes in October. Coal India was established on 1 November 1975; the release sets its FY 2026-27 production target at 815 million tonnes, which is a target rather than a reported achievement.$$,
$$Coal India Marks 51 Glorious Years with Record-Breaking Performance in October 2026$$,
$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2331230$$,
$$Ministry of Coal / Press Information Bureau$$, $$2026-11-01$$,
$$["Coal India's October production was 67.2 million tonnes.","Its total October supply was 70.3 million tonnes.","Supply to the power sector was 57.1 million tonnes.","Coal India was established on 1 November 1975."]$$::jsonb,
$$[{"question":"Are Coal India's production and total supply the same operating measure?","answer":"No. The release reports them separately: 67.2 million tonnes of production and 70.3 million tonnes of total supply in October."}]$$::jsonb,
$${"title":"Coal-sector operating indicators","steps":["Coal is produced at mines.","Logistics move the coal to users.","Supply measures delivered or dispatched coal.","Railway rake loading is one indicator of evacuation capacity."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-02-rbi-services-trade-september$$, $$2026-11-02$$,
$$RBI releases September services-trade data: receipts at US$39.31 billion$$,
$$The Reserve Bank of India reported provisional services exports, termed receipts, of US$39.305 billion for September 2026 and services imports, termed payments, of US$20.097 billion. The release gives year-on-year growth rates of 7.2% for receipts and 12.6% for payments.$$,
$$This is a practical external-sector data point. It helps candidates distinguish merchandise trade from services trade and understand why RBI labels service exports as receipts and service imports as payments.$$,
$$The data for July to September are provisional. The September figures imply a positive services balance when receipts exceed payments, but they are not a complete current-account figure: income, transfers and other balance-of-payments components are accounted for separately. The growth rates compare with the corresponding month of the previous year and were revised using balance-of-payments statistics.$$,
$$Monthly Data on India's International Trade in Services for the Month of September 2026$$,
$$https://www.rbi.org.in/Scripts/BS_PressReleaseDisplay.aspx?prid=63893$$,
$$Reserve Bank of India$$, $$2026-10-30$$,
$$["September 2026 services receipts were US$39.305 billion.","September services payments were US$20.097 billion.","The respective year-on-year growth rates were 7.2% and 12.6%.","The July-September values are provisional."]$$::jsonb,
$$[{"question":"In RBI's services-trade table, what do 'receipts' represent?","answer":"Receipts represent services exports; payments represent services imports."}]$$::jsonb,
$${"title":"Services-trade reading","steps":["Service exports generate receipts.","Service imports generate payments.","Receipts above payments create a services surplus.","Other balance-of-payments components are needed for the full current account."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-02-sebi-fpi-kyc-review-periodicity$$, $$2026-11-02$$,
$$SEBI rationalises the periodic KYC-review framework for foreign portfolio investors$$,
$$SEBI issued a circular rationalising the periodicity of Know Your Client review for foreign portfolio investors (FPIs). The update is a late regulatory development from 30 October and is accompanied by a SEBI press release on easing compliance for FPIs.$$,
$$This is a useful capital-markets regulation item. It links SEBI's oversight of FPIs with KYC due diligence, while avoiding the mistake of treating a review-cycle change as an exemption from identity checks or anti-money-laundering obligations.$$,
$$An FPI is an investor registered to invest in Indian financial markets under the applicable framework. KYC means Know Your Client: it is the process of establishing and maintaining customer identity and related due-diligence information. The circular concerns the periodic review framework for FPIs; it does not eliminate the underlying KYC requirement.$$,
$$Rationalisation of periodicity of KYC review for FPIs$$,
$$https://www.sebi.gov.in/legal/circulars/oct-2026/rationalisation-of-periodicity-of-kyc-review-for-fpis_105504.html$$,
$$Securities and Exchange Board of India$$, $$2026-10-30$$,
$$["SEBI issued the circular on 30 October 2026.","The circular concerns foreign portfolio investors, or FPIs.","KYC stands for Know Your Client.","The action rationalises periodic KYC review; it does not remove KYC from the FPI framework."]$$::jsonb,
$$[{"question":"Which regulator issued the circular on periodic KYC review for FPIs?","answer":"The Securities and Exchange Board of India (SEBI)."}]$$::jsonb,
$${"title":"FPI KYC oversight","steps":["An investor seeks or holds FPI registration.","KYC information establishes and maintains due diligence.","The regulator specifies the periodic-review framework.","Intermediaries apply the framework to the relevant FPI relationship."]}$$::jsonb, $$published$$, now()
)
on conflict (slug) do update set
  title = excluded.title, summary = excluded.summary, why_it_matters = excluded.why_it_matters,
  background = excluded.background, source_title = excluded.source_title, source_url = excluded.source_url,
  source_publisher = excluded.source_publisher, source_published_on = excluded.source_published_on,
  prelims_takeaways = excluded.prelims_takeaways, quick_check = excluded.quick_check,
  visual_data = excluded.visual_data, status = excluded.status, reviewed_at = excluded.reviewed_at,
  updated_at = now();

insert into public.current_affairs_exam_tags (brief_id, exam_id)
select briefs.id, exams.id from public.current_affairs_briefs briefs cross join public.exams exams
where briefs.slug in (
$$2026-11-02-digi-yatra-international-trials$$,
$$2026-11-02-coal-imports-august$$,
$$2026-11-02-air-chief-marshal-ashutosh-dixit-vayu$$,
$$2026-11-02-cisf-functional-sector-structure$$,
$$2026-11-02-bengaluru-mumbai-vande-bharat-sleeper$$,
$$2026-11-02-coal-india-october-records$$,
$$2026-11-02-rbi-services-trade-september$$,
$$2026-11-02-sebi-fpi-kyc-review-periodicity$$
) and exams.slug in ($$cuet$$, $$ssc-cgl$$, $$uppsc-ro-aro$$, $$up-secretariat-ro-aro$$)
on conflict do nothing;
